import{z as i,x as l,o as E,c as n,q as A,j as o,D as e,d as t,s,S as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"异构 SoC 与 big.LITTLE","description":"","frontmatter":{"title":"异构 SoC 与 big.LITTLE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heterogeneous-soc.md","filePath":"cs/heterogeneous-soc.md","lastUpdated":1791413859000}'),p={name:"cs/heterogeneous-soc.md"};function c(d,a,T,h,m,D){const r=l("Mermaid");return E(),n("div",null,[a[2]||(a[2]=A('<h1 id="异构-soc-与-big-little" tabindex="-1">异构 SoC 与 big.LITTLE <a class="header-anchor" href="#异构-soc-与-big-little" aria-label="Permalink to &quot;异构 SoC 与 big.LITTLE&quot;">​</a></h1><div class="epigraph"><p>同一 ISA 上做一颗宽乱序大核与一颗窄顺序小核：峰值走大核，后台与能效走小核；调度器要在迁移代价与功耗之间选。</p><footer>—— 据 Kumar et al., Single-ISA Heterogeneous Multi-Core Architectures；ARM big.LITTLE 公开叙述 整理</footer></div><p><a href="/cs/pim-near-memory">上一课</a> 把一种异构（近存）放到内存侧。手机与服务器 SoC 上更常见的是 <strong>同一 ISA、不同微结构</strong> 的 CPU 簇，外加 GPU/DSA。本课不重讲 PIM 命令。缺口是 <strong>big.LITTLE：异构多核的性能–功耗前沿，以及任务往哪颗核上放。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全用 <a href="/cs/deep-pipeline-clock">深流水乱序</a> 核：闲时漏电与面积吃不消。全用小核：单线程串行段（Amdahl）崩。缺口不是 Flynn 的 MIMD 定义，而是<strong>单 ISA 异构：迁移只需拷贝架构状态，不必重编译，但 <a href="/cs/tlb-hierarchy-pwc">TLB</a>、cache、预取器都是冷的。</strong></p><p><span class="marginnote">Kumar 等展示单 ISA 异构的能效。ARM big.LITTLE / DynamIQ：共享缓存或按簇，OS 用容量与频率点做调度。这不是 GPU SIMT，也不是 big.LITTLE 当广告词乱用。</span></p><p><span class="marginnote">术语翻译：单 ISA 异构是说大小核认同一种指令集，只是「施工队」不同——大核又宽又深、小核又窄又短。所以任务迁移只需搬一份寄存器状态，程序不用重新编译；换成 CPU 加 GPU 那种不同 ISA 的组合，就没有这个待遇。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>大核：宽发射、深窗口、激进预取。小核：短管线、窄发射、简单预测。迁移：保存 ISA 状态，在目标核上恢复；可选共享 L3 减少冷缺失。加速器：不同 ISA，走驱动队列，见 <a href="/cs/dsa-accelerator">DSA</a>。</p>',9)),(E(),o(B,null,{default:e(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20OS%5B%22%E6%8C%89%E8%B4%9F%E8%BD%BD%2F%E5%8A%9F%E8%80%97%E9%80%89%E7%B0%87%22%5D%0A%20%20OS%20--%3E%20BIG%5B%22%E4%B9%B1%E5%BA%8F%E5%A4%A7%E6%A0%B8%22%5D%0A%20%20OS%20--%3E%20LITTLE%5B%22%E5%B0%8F%E6%A0%B8%22%5D%0A%20%20OS%20--%3E%20ACC%5B%22%E9%9D%9E%E5%AF%B9%E7%A7%B0%20ISA%20%E5%8A%A0%E9%80%9F%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>调度错误：把长串行放小核，或把常驻后台放大核空转。迁移过频则 <a href="/cs/mlp-memory-parallelism">MLP</a> 与 BTB 全冷，比留在稍慢的核更差。一致性：大小核仍走 <a href="/cs/moesi-mesif">MOESI/MESIF</a>，频率不同使响应时间不对称。</p><p>共享 L3 让迁移后数据还在，但预取器、uop cache、<a href="/cs/loop-stream-buffer">循环流缓冲</a> 仍冷。短任务迁移不划算：上下文切换那一截可能长过任务本身。</p><p>迁移一次要付哪些冷启动税、何时划算：</p>',4)),(E(),o(B,null,{default:e(()=>[s(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E4%BB%BB%E5%8A%A1%E4%BB%8E%E5%A4%A7%E6%A0%B8%E8%BF%81%E5%BE%80%E5%B0%8F%E6%A0%B8%22%5D%20--%3E%20A%5B%22%E4%BF%9D%E5%AD%98%E5%B9%B6%E6%81%A2%E5%A4%8D%E6%9E%B6%E6%9E%84%E7%8A%B6%E6%80%81%22%5D%0A%20%20A%20--%3E%20B%5B%22TLB%20%E5%85%A8%E7%A9%BA%3A%20%E9%80%90%E9%A1%B5%E9%87%8D%E6%96%B0%E5%A1%AB%E5%85%85%22%5D%0A%20%20B%20--%3E%20C%5B%22cache%20%E5%86%B7%3A%20%E6%95%B0%E6%8D%AE%E9%80%90%E6%9D%A1%E9%87%8D%E5%8F%96%22%5D%0A%20%20C%20--%3E%20D%5B%22%E9%A2%84%E5%8F%96%E5%99%A8%E4%B8%8E%20BTB%20%E5%86%B7%3A%20%E5%89%8D%E5%87%A0%E5%8D%83%E6%9D%A1%E6%8C%87%E4%BB%A4%E6%97%A0%E5%8A%A0%E9%80%9F%22%5D%0A%20%20D%20--%3E%20E%7B%22%E4%BB%BB%E5%8A%A1%E5%89%A9%E4%BD%99%E6%97%B6%E9%95%BF%20%E5%A4%9F%E4%B8%8D%E5%A4%9F%E6%91%8A%E5%B9%B3%E5%BC%80%E9%94%80%3F%22%7D%0A%20%20E%20--%20%22%E4%BB%BB%E5%8A%A1%E5%A4%AA%E7%9F%AD%22%20--%3E%20F%5B%22%E4%B8%8D%E8%BF%81%E7%A7%BB%2C%20%E7%95%99%E5%9C%A8%E5%8E%9F%E6%A0%B8%22%5D%0A%20%20E%20--%20%22%E4%BB%BB%E5%8A%A1%E5%A4%9F%E9%95%BF%22%20--%3E%20G%5B%22%E8%BF%81%E7%A7%BB%E5%87%80%E8%B5%9A%E8%83%BD%E6%95%88%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<p><span class="marginnote">数字实例：迁移后 TLB、缓存、预取器全是冷的，一个随后只跑几十万条指令的短任务，可能大半时间都花在等缓存重填；跑上千万条指令的长任务，冷启动被摊薄到百分之一以下——这就是「短任务迁移不划算」的量化直觉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写具体 cpufreq governor。片上如何把这些核连起来是下一课 NoC。拓扑再下一课。</p><p>后课默认：异构是调度问题加迁移税。核间通信走片上网络，而不是假定广播总线。</p><p><span class="marginnote">常见误区：把 big.LITTLE 理解成「大核快所以一直用大核」。实际上手机 CPU 大部分时间是小核在低频待命，大核只在突发负载时短促登场；整机的续航主要由小核侧的功耗决定，峰值性能才是大核的事。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单 ISA 异构用大小核切性能/瓦；迁移有微结构冷启动税。</li><li>加速器是另一 ISA，靠队列。</li><li>片上互连形状是下一课 NoC。</li><li>出处：Kumar et al.；ARM big.LITTLE；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',7))])}const u=i(p,[["render",c]]);export{_ as __pageData,u as default};
